def find_groups(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    groups = {}

    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val in (0, 6):
                continue
            if (r, c) in visited:
                continue

            comp = []
            stack = [(r, c)]
            while stack:
                cr, cc = stack.pop()
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                comp.append((cr, cc))
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < h and 0 <= nc < w:
                        if grid[nr][nc] == val and (nr, nc) not in visited:
                            stack.append((nr, nc))

            rows_min = min(cr for cr, cc in comp)
            rows_max = max(cr for cr, cc in comp)
            cols_min = min(cc for cr, cc in comp)
            cols_max = max(cc for cr, cc in comp)

            groups[val] = {
                'cells': comp,
                'count': len(comp),
                'rows_range': (rows_min, rows_max),
                'cols_range': (cols_min, cols_max)
            }

    return groups

