def solve_test_pattern(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])

    # Find background
    counts = Counter(val for row in grid for val in row)
    bg = counts.most_common(1)[0][0]

    # Collect non-bg cells
    non_bg_items = []
    for r in range(h):
        for c in range(w):
            cell_val = grid[r][c]
            if cell_val != bg:
                non_bg_items.append((r, c, cell_val))

    marker_val = 2
    fill_val = [v for v in set(c[2] for c in non_bg_items) if v != 2][0]

    # Get marker positions and which columns they're in
    marker_cells = [(r,c,v) for r,c,v in non_bg_items if v == marker_val]

    all_marker_cols = sorted(set(c for r,c,v in marker_cells))
    print(f"Marker cols: {all_marker_cols}")

    result = [row[:] for row in grid]

    # Get top boundary marker columns (where markers appear at row 0)
    top_row_markers = [c for c in all_marker_cols if any(m[0] == 0 and m[1] == c and m[2] == marker_val for m in marker_cells)]
    print(f"Top-boundary marker cols: {top_row_markers}")

    # Get marker cols that ALSO contain fill-val cells
    fill_col_map = {}
    for r,c,v in non_bg_items:
        if v == fill_val:
            fill_col_map[c] = True
    marker_cols_with_fill = [c for c in all_marker_cols if c in fill_col_map]
    print(f"Marker cols with fill-val: {marker_cols_with_fill}")

    # Find when we've seen ALL marker cols that have fill-val
    if marker_cols_with_fill:
        first_see_rows = {}
        for r,c,v in non_bg_items:
            if v == fill_val and c in marker_cols_with_fill:
                if c not in first_see_rows:
                    first_see_rows[c] = r

        if first_see_rows:
            transition_row = max(first_see_rows.values())
            print(f"Transition row (after all marker-fill-cols seen): {transition_row}")

            # Phase 1: Before transition - only top-boundary marker cols
            start = 1 if 0 not in fill_col_map else 1
            for r in range(start, transition_row):
                for c in top_row_markers:
                    if grid[r][c] == bg:
                        result[r][c] = fill_val

            # Phase 2: At/after transition - ALL marker cols  
            for r in range(transition_row, h-1):  # Interior rows only
                for c in all_marker_cols:
                    if grid[r][c] == bg:
                        result[r][c] = fill_val
        else:
            # Never see all marker-fill-cols (edge case)
            for r in range(1, h-1):
                for c in top_row_markers:
                    if grid[r][c] == bg:
                        result[r][c] = fill_val
    else:
        # No marker cols have fill-val - just use top boundary cols
        for r in range(1, h-1):
            for c in top_row_markers:
                if grid[r][c] == bg:
                    result[r][c] = fill_val

    # Convert original fill-val cells to 4
    for r,c,v in non_bg_items:
        if v == fill_val:
            result[r][c] = 4

    return result

